     1→import { Block, Screen, Text } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import { MatrixService } from "modules/matrix-client/services";
     4→import { addDateDividers, getEventId } from "modules/matrix-client/utils";
     5→import { useEffect, useMemo, useRef, useState } from "react";
     6→import {
     7→  ActivityIndicator,
     8→  FlatList,
     9→  Image,
    10→  KeyboardAvoidingView,
    11→  type NativeScrollEvent,
    12→  type NativeSyntheticEvent,
    13→  StyleSheet,
    14→} from "react-native";
    15→import { useSafeAreaInsets } from "react-native-safe-area-context";
    16→import { Button, Loading } from "shared/components";
    17→import { Colors } from "shared/styles";
    18→import {
    19→  DateDivider,
    20→  MessageContentBottomSheet,
    21→  RoomHeader,
    22→  RoomInput,
    23→  SingleMessageType,
    24→} from "./fragments";
    25→import { useRoomInitialization, useRoomTimeline } from "./hooks";
    26→import { filterSameStateKey, handleIsPreviousSameSender } from "./utils";
    27→
    28→export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
    29→  route,
    30→  navigation,
    31→}) => {
    32→  const { roomId } = route.params;
    33→  const client = MatrixService.instance;
    34→  const room = client?.getRoom(roomId);
    35→  const insets = useSafeAreaInsets();
    36→  const flatListRef = useRef<FlatList>(null);
    37→  /* Track whether list is scrolled to bottom */
    38→  const isAtBottomRef = useRef(true);
    39→  const [showScrollDown, setShowScrollDown] = useState(false);
    40→  const hasActiveCall = room?.hasActiveRoomCall();
    41→
    42→  const {
    43→    events,
    44→    loadingMessage,
    45→    refreshing,
    46→    updateTrigger,
    47→    loadMoreMessages,
    48→    markAsRead,
    49→  } = useRoomTimeline({
    50→    room,
    51→    roomId,
    52→  });
    53→
    54→  const { roomMembers, hasNoCallOption } = useRoomInitialization({ room });
    55→
    56→  const sortedEvents = useMemo(() => {
    57→    const sorted = [...events].sort(
    58→      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    59→    );
    60→
    61→    return filterSameStateKey(sorted);
    62→  }, [events]);
    63→
    64→  /**Events with date dividers */
    65→  const eventsWithDividers = useMemo(() => {
    66→    return addDateDividers(sortedEvents);
    67→  }, [sortedEvents]);
    68→
    69→  const handleLoadMore = async () => {
    70→    setShowScrollDown(false);
    71→    await loadMoreMessages();
    72→  };
    73→
    74→  const handleScrollDown = () => {
    75→    flatListRef.current?.scrollToEnd({ animated: true });
    76→    setShowScrollDown(false);
    77→  };
    78→
    79→  const handleOnScroll = ({
    80→    nativeEvent,
    81→  }: NativeSyntheticEvent<NativeScrollEvent>) => {
    82→    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
    83→    const paddingToBottom = 100;
    84→    const atBottom =
    85→      layoutMeasurement.height + contentOffset.y >=
    86→      contentSize.height - paddingToBottom;
    87→    isAtBottomRef.current = atBottom;
    88→    if (!atBottom) return;
    89→    setShowScrollDown(false);
    90→    markAsRead();
    91→  };
    92→
    93→  // Show scroll down button if not at bottom and not own message
    94→  useEffect(() => {
    95→    if (isAtBottomRef.current || sortedEvents[0]?.isOwn) return;
    96→
    97→    setShowScrollDown(true);
    98→  }, [sortedEvents]);
    99→
   100→  const handleStartCall = () => {
   101→    if (!client || !room) {
   102→      console.error("Client or room not available");
   103→      return;
   104→    }
   105→
   106→    navigation.navigate("elementCall", {
   107→      roomId,
   108→      roomName: room.displayName(),
   109→    });
   110→  };
   111→
   112→  if (!room) return null;
   113→
   114→  return (
   115→    <Screen hideTopSafeArea scrollable={false}>
   116→      <RoomHeader
   117→        room={room}
   118→        roomMembers={roomMembers}
   119→        hasActiveCall={hasActiveCall ?? false}
   120→        hasNoCallOption={hasNoCallOption}
   121→        topInset={insets.top}
   122→        onBack={() => navigation.goBack()}
   123→        onRoomDetails={() => navigation.navigate("roomDetails", { room })}
   124→        onStartCall={handleStartCall}
   125→      />
   126→
   127→      {loadingMessage ? (
   128→        <Loading />
   129→      ) : (
   130→        <KeyboardAvoidingView style={{ flex: 1 }} behavior="padding">
   131→          {refreshing && (
   132→            <Block align="center" justify="center" width="100%" paddings={40}>
   133→              <ActivityIndicator size="large" color={Colors.primary} />
   134→            </Block>
   135→          )}
   136→          <FlatList
   137→            ref={flatListRef}
   138→            data={eventsWithDividers}
   139→            keyExtractor={(item) => {
   140→              if (item.type === "divider") return item.id;
   141→
   142→              return getEventId(item.data) ?? "";
   143→            }}
   144→            extraData={updateTrigger}
   145→            contentContainerStyle={styles.listContent}
   146→            onContentSizeChange={() => {
   147→              if (!isAtBottomRef.current) return;
   148→              // Auto-scroll only if already at the bottom
   149→              flatListRef.current?.scrollToEnd({ animated: false });
   150→            }}
   151→            onRefresh={handleLoadMore}
   152→            refreshing={refreshing}
   153→            onScroll={handleOnScroll}
   154→            renderItem={({ item }) => {
   155→              if (item.type === "divider") {
   156→                return <DateDivider date={item.date} />;
   157→              }
   158→
   159→              // For events, calculate the index in the original sortedEvents array
   160→              const eventIndex = sortedEvents.findIndex(
   161→                (e) => getEventId(e) === getEventId(item.data),
   162→              );
   163→
   164→              return (
   165→                <SingleMessageType
   166→                  event={item.data}
   167→                  isPreviousSameSender={handleIsPreviousSameSender(
   168→                    sortedEvents,
   169→                    item.data,
   170→                    eventIndex,
   171→                  )}
   172→                />
   173→              );
   174→            }}
   175→          />
   176→          <MessageContentBottomSheet />
   177→
   178→          {showScrollDown && (
   179→            <Block
   180→              absolute
   181→              offsets={{ right: 0, bottom: 100 }}
   182→              align="center"
   183→              justify="center"
   184→              width="100%"
   185→            >
   186→              <Button.Outline size="medium" onPress={handleScrollDown}>
   187→                <Text>New messages</Text>
   188→                <Image source={require("assets/icons/arrow-down.png")} />
   189→              </Button.Outline>
   190→            </Block>
   191→          )}
   192→          <RoomInput roomId={roomId} />
   193→        </KeyboardAvoidingView>
   194→      )}
   195→    </Screen>
   196→  );
   197→};
   198→
   199→const styles = StyleSheet.create({
   200→  image: {
   201→    width: 32,
   202→    height: 32,
   203→    borderRadius: 48,
   204→  },
   205→  listContent: {
   206→    paddingHorizontal: 20,
   207→    paddingTop: 12,
   208→    paddingBottom: 20,
   209→  },
   210→  callButton: {
   211→    width: 36,
   212→    height: 36,
   213→    borderRadius: 18,
   214→    justifyContent: "center",
   215→    alignItems: "center",
   216→  },
   217→  callIcon: {
   218→    width: 20,
   219→    height: 20,
   220→    resizeMode: "contain",
   221→  },
   222→  callButtonCustom: {
   223→    backgroundColor: "rgba(255, 255, 255, 0.2)",
   224→    borderRadius: 18,
   225→    paddingHorizontal: 12,
   226→    paddingVertical: 8,
   227→  },
   228→  chatButton: {
   229→    display: "flex",
   230→    gap: 12,
   231→    flex: 1,
   232→    flexDirection: "column",
   233→  },
   234→  phoneIcon: {
   235→    width: 16,
   236→    height: 16,
   237→  },
   238→  blurOverlay: {
   239→    position: "absolute",
   240→    top: 0,
   241→    left: 0,
   242→    right: 0,
   243→    bottom: 0,
   244→    zIndex: 1,
   245→    opacity: 0.5,
   246→    width: "120%",
   247→    pointerEvents: "none",
   248→  },
   249→});
