     1→import type {
     2→  EventTimelineItem,
     3→  RoomInterface,
     4→  TaskHandleInterface,
     5→  TimelineInterface,
     6→} from "@unomed/react-native-matrix-sdk";
     7→import {
     8→  DateDividerMode,
     9→  MessageType_Tags,
    10→  MsgLikeKind_Tags,
    11→  ReceiptType,
    12→  TimelineDiff_Tags,
    13→  TimelineFilter,
    14→  TimelineFocus,
    15→  TimelineItemContent_Tags,
    16→  TimelineReadReceiptTracking,
    17→} from "@unomed/react-native-matrix-sdk";
    18→import { useSetAtom } from "jotai";
    19→import { MatrixAtoms } from "modules/matrix-client/jotai";
    20→import { getEventId } from "modules/matrix-client/utils";
    21→import { NavigationContainerRef } from "modules/navigation/const";
    22→import { useCallback, useEffect, useRef, useState } from "react";
    23→
    24→/** Maximum age for a verification request to be considered valid (5 minutes) */
    25→const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;
    26→
    27→/** Check if an event is a verification request */
    28→const isVerificationRequest = (event: EventTimelineItem): boolean => {
    29→  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
    30→  const kind = event.content.inner.content.kind;
    31→  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
    32→  const msgType = kind.inner.content.msgType;
    33→  return (
    34→    msgType?.tag === MessageType_Tags.Other &&
    35→    msgType.inner.msgtype === "m.key.verification.request"
    36→  );
    37→};
    38→
    39→/** Check if a verification request is recent enough to be handled */
    40→const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
    41→  const eventTimestamp = Number(event.timestamp);
    42→  const now = Date.now();
    43→  const age = now - eventTimestamp;
    44→  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
    45→};
    46→
    47→interface Props {
    48→  room: RoomInterface | undefined;
    49→  roomId: string;
    50→}
    51→
    52→export const useRoomTimeline = ({ room, roomId }: Props) => {
    53→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
    54→  const [loadingMessage, setLoadingMessage] = useState(true);
    55→  /** Track processed verification request IDs to avoid duplicates */
    56→  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
    57→  const [refreshing, setRefreshing] = useState(false);
    58→  const [updateTrigger, setUpdateTrigger] = useState(0);
    59→  const eventIdsRef = useRef<Set<string>>(new Set());
    60→  const timelineRef = useRef<TimelineInterface | null>(null);
    61→  const isPaginatingRef = useRef(false);
    62→  const timelinePaginateNumber = useRef<number>(20);
    63→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    64→
    65→  const upsertEvents = (incoming: EventTimelineItem[]) => {
    66→    setEvents((prev) => {
    67→      const next = [...prev];
    68→      for (const e of incoming) {
    69→        const id = getEventId(e);
    70→        if (!id) continue;
    71→        if (!eventIdsRef.current.has(id)) {
    72→          eventIdsRef.current.add(id);
    73→          next.push(e);
    74→        }
    75→      }
    76→      return next;
    77→    });
    78→  };
    79→
    80→  const handleVerificationRequest = (info: {
    81→    senderId: string;
    82→    flowId: string;
    83→  }) => {
    84→    setVerificationStatus("incomingRequest");
    85→    NavigationContainerRef.navigate("verifyUser", {
    86→      userId: info.senderId,
    87→      flowId: info.flowId,
    88→    });
    89→  };
    90→
    91→  const checkForVerificationRequests = useCallback(
    92→    (incoming: EventTimelineItem[]) => {
    93→      for (const event of incoming) {
    94→        if (event.isOwn) continue;
    95→
    96→        if (
    97→          !isVerificationRequest(event) ||
    98→          !isRecentVerificationRequest(event)
    99→        ) {
   100→          continue;
   101→        }
   102→
   103→        const flowId = getEventId(event);
   104→        if (!flowId) continue;
   105→
   106→        if (processedVerificationRequestsRef.current.has(flowId)) continue;
   107→
   108→        processedVerificationRequestsRef.current.add(flowId);
   109→
   110→        handleVerificationRequest({
   111→          senderId: event.sender,
   112→          flowId,
   113→        });
   114→
   115→        // Only handle one at a time
   116→        break;
   117→      }
   118→    },
   119→    [],
   120→  );
   121→
   122→  const markAsRead = async () => {
   123→    if (!room) return;
   124→
   125→    try {
   126→      await room.markAsRead(ReceiptType.Read);
   127→    } catch (error) {
   128→      console.error("Failed to mark room as read:", error);
   129→    }
   130→  };
   131→
   132→  const loadMoreMessages = async () => {
   133→    if (!room || !timelineRef.current) return;
   134→
   135→    isPaginatingRef.current = true;
   136→    setRefreshing(true);
   137→
   138→    try {
   139→      await timelineRef.current.paginateBackwards(
   140→        timelinePaginateNumber.current,
   141→      );
   142→      timelinePaginateNumber.current += 20;
   143→    } catch (error) {
   144→      console.error("Failed to load more messages:", error);
   145→    } finally {
   146→      setRefreshing(false);
   147→      isPaginatingRef.current = false;
   148→    }
   149→  };
   150→
   151→  useEffect(() => {
   152→    if (!room) return;
   153→
   154→    // Reset state when room changes
   155→    setEvents([]);
   156→    eventIdsRef.current.clear();
   157→
   158→    let timelineListenerHandle: TaskHandleInterface | null = null;
   159→
   160→    const initRoomTimeline = async () => {
   161→      try {
   162→        const timeline = await room.timelineWithConfiguration({
   163→          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
   164→          filter: new TimelineFilter.All(),
   165→          internalIdPrefix: undefined,
   166→          dateDividerMode: DateDividerMode.Daily,
   167→          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
   168→          reportUtds: false,
   169→        });
   170→
   171→        // Store timeline in ref for reuse in pagination
   172→        timelineRef.current = timeline;
   173→
   174→        await timeline.paginateBackwards(timelinePaginateNumber.current);
   175→        timelinePaginateNumber.current += 20;
   176→        setLoadingMessage(false);
   177→
   178→        // Set up timeline listener for real-time updates
   179→        timelineListenerHandle = await timeline.addListener({
   180→          onUpdate: (diffs) => {
   181→            markAsRead();
   182→            // Trigger re-render to update read receipts and other event properties
   183→            setUpdateTrigger((prev) => prev + 1);
   184→            diffs.forEach((diff) => {
   185→              const change = diff.tag;
   186→              switch (change) {
   187→                case TimelineDiff_Tags.Append: {
   188→                  const newItems = diff.inner.values;
   189→                  if (newItems.length) {
   190→                    const eventItems = newItems
   191→                      .map((i) => i.asEvent())
   192→                      .filter((i): i is EventTimelineItem => !!i);
   193→
   194→                    if (eventItems.length > 0) {
   195→                      upsertEvents(eventItems);
   196→                      checkForVerificationRequests(eventItems);
   197→                    }
   198→                  }
   199→                  break;
   200→                }
   201→                case TimelineDiff_Tags.Insert: {
   202→                  const { value } = diff.inner;
   203→                  const ev = value.asEvent();
   204→                  if (ev) {
   205→                    upsertEvents([ev]);
   206→                    checkForVerificationRequests([ev]);
   207→                  }
   208→                  break;
   209→                }
   210→                case TimelineDiff_Tags.Set: {
   211→                  const { index, value } = diff.inner;
   212→                  const ev = value.asEvent();
   213→                  if (ev) {
   214→                    const id = getEventId(ev);
   215→                    if (!id) break;
   216→
   217→                    setEvents((prev) => {
   218→                      const next = [...prev];
   219→                      // Guard against out-of-range (indexes may include non-event items upstream)
   220→                      if (index >= 0 && index < next.length) {
   221→                        // Check if we're updating the same event or creating a duplicate
   222→                        const existingId = getEventId(next[index]);
   223→                        if (existingId === id || !eventIdsRef.current.has(id)) {
   224→                          next[index] = ev;
   225→                        }
   226→                      } else {
   227→                        // If index doesn't line up, check for duplicates before adding
   228→                        if (!eventIdsRef.current.has(id)) {
   229→                          next.push(ev);
   230→                        }
   231→                      }
   232→                      // Rebuild Set from next
   233→                      eventIdsRef.current = new Set(
   234→                        next.map(getEventId).filter(Boolean) as string[],
   235→                      );
   236→                      return next;
   237→                    });
   238→                  }
   239→                  break;
   240→                }
   241→                case TimelineDiff_Tags.Remove: {
   242→                  const { index: removeIndex } = diff.inner;
   243→                  setEvents((prev) => {
   244→                    const next = prev.filter((_, idx) => idx !== removeIndex);
   245→                    eventIdsRef.current = new Set(
   246→                      next.map(getEventId).filter(Boolean) as string[],
   247→                    );
   248→                    return next;
   249→                  });
   250→                  break;
   251→                }
   252→                case TimelineDiff_Tags.PushFront: {
   253→                  const { value } = diff.inner;
   254→                  const ev = value.asEvent();
   255→                  if (ev) {
   256→                    const id = getEventId(ev);
   257→                    if (!id) break;
   258→
   259→                    setEvents((prev) => {
   260→                      // Check for duplicate inside setState to prevent race conditions
   261→                      if (eventIdsRef.current.has(id)) return prev;
   262→                      eventIdsRef.current.add(id);
   263→                      return [ev, ...prev];
   264→                    });
   265→                    checkForVerificationRequests([ev]);
   266→                  }
   267→                  break;
   268→                }
   269→                case TimelineDiff_Tags.PushBack: {
   270→                  const { value } = diff.inner;
   271→                  const ev = value.asEvent();
   272→                  if (ev) {
   273→                    const id = getEventId(ev);
   274→                    if (!id) break;
   275→
   276→                    setEvents((prev) => {
   277→                      // Check for duplicate inside setState to prevent race conditions
   278→                      if (eventIdsRef.current.has(id)) return prev;
   279→                      eventIdsRef.current.add(id);
   280→                      return [...prev, ev];
   281→                    });
   282→                    checkForVerificationRequests([ev]);
   283→                  }
   284→                  break;
   285→                }
   286→                case TimelineDiff_Tags.Reset: {
   287→                  const resetItems = diff.inner.values;
   288→                  if (resetItems.length) {
   289→                    const eventItems = resetItems
   290→                      .map((i) => i.asEvent())
   291→                      .filter((i): i is EventTimelineItem => !!i);
   292→
   293→                    // Deduplicate events in case Reset contains duplicates
   294→                    const seenIds = new Set<string>();
   295→                    const uniqueEvents: EventTimelineItem[] = [];
   296→
   297→                    for (const event of eventItems) {
   298→                      const id = getEventId(event);
   299→                      if (id && !seenIds.has(id)) {
   300→                        seenIds.add(id);
   301→                        uniqueEvents.push(event);
   302→                      }
   303→                    }
   304→
   305→                    eventIdsRef.current = seenIds;
   306→                    setEvents(uniqueEvents);
   307→                  }
   308→                  break;
   309→                }
   310→                case TimelineDiff_Tags.Truncate: {
   311→                  const { length: cut } = diff.inner;
   312→                  setEvents((prev) => {
   313→                    const next = prev.slice(0, cut);
   314→                    eventIdsRef.current = new Set(
   315→                      next.map(getEventId).filter(Boolean) as string[],
   316→                    );
   317→                    return next;
   318→                  });
   319→                  break;
   320→                }
   321→                default:
   322→                  console.log("Unknown timeline change type:", change);
   323→              }
   324→            });
   325→          },
   326→        });
   327→      } catch (error) {
   328→        console.error("Failed to initialize room timeline:", error);
   329→        return null;
   330→      }
   331→    };
   332→
   333→    initRoomTimeline();
   334→
   335→    return () => {
   336→      timelineListenerHandle?.cancel?.();
   337→      timelineRef.current = null;
   338→    };
   339→  }, [roomId, checkForVerificationRequests]);
   340→
   341→  useEffect(() => {
   342→    markAsRead().catch(console.error);
   343→  }, []);
   344→
   345→  return {
   346→    events,
   347→    loadingMessage,
   348→    refreshing,
   349→    timelineRef,
   350→    isPaginatingRef,
   351→    updateTrigger,
   352→    loadMoreMessages,
   353→    markAsRead,
   354→  };
   355→};
