     1→import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
     2→
     3→type TimelineListItem =
     4→  | { type: "event"; data: EventTimelineItem }
     5→  | { type: "divider"; date: string; id: string };
     6→
     7→const formatTimelineDate = (timestamp: bigint): string => {
     8→  const date = new Date(Number(timestamp));
     9→  const today = new Date();
    10→  const yesterday = new Date(today);
    11→  yesterday.setDate(yesterday.getDate() - 1);
    12→
    13→  const dateOnly = new Date(
    14→    date.getFullYear(),
    15→    date.getMonth(),
    16→    date.getDate(),
    17→  );
    18→  const todayOnly = new Date(
    19→    today.getFullYear(),
    20→    today.getMonth(),
    21→    today.getDate(),
    22→  );
    23→  const yesterdayOnly = new Date(
    24→    yesterday.getFullYear(),
    25→    yesterday.getMonth(),
    26→    yesterday.getDate(),
    27→  );
    28→
    29→  if (dateOnly.getTime() === todayOnly.getTime()) return "Today";
    30→
    31→  if (dateOnly.getTime() === yesterdayOnly.getTime()) return "Yesterday";
    32→
    33→  return date.toLocaleDateString("en-US", {
    34→    weekday: "long",
    35→    year: "numeric",
    36→    month: "long",
    37→    day: "numeric",
    38→  });
    39→};
    40→
    41→/** Helper function to group events by date and add dividers */
    42→export const addDateDividers = (
    43→  events: EventTimelineItem[],
    44→): TimelineListItem[] => {
    45→  const result: TimelineListItem[] = [];
    46→  let lastDate: string | null = null;
    47→
    48→  for (const event of events) {
    49→    const eventDate = formatTimelineDate(event.timestamp);
    50→
    51→    if (eventDate !== lastDate) {
    52→      result.push({
    53→        type: "divider",
    54→        date: eventDate,
    55→        id: `divider-${event.timestamp}`,
    56→      });
    57→      lastDate = eventDate;
    58→    }
    59→
    60→    result.push({ type: "event", data: event });
    61→  }
    62→
    63→  return result;
    64→};
