interface EventTimelineItem {
  timestamp: bigint;
  sender: string;
  senderProfile: ProfileDetails | null;
  isOwn: boolean;
  canBeRepliedTo: boolean;
  content: TimelineItemContent; // Discriminated union with various content types
  eventOrTransactionId: {
    tag: "EventId" | "TransactionId";
    inner?: { eventId: string };
  };
}
```

**Message Identification:**
- Uses `getEventId(event)` utility to extract unique event IDs
- Event ID extracted from: `event.eventOrTransactionId.inner.eventId` (when tag === "EventId")
- See: `/Users/stjepandzojic/projects/cloakanddagger/src/modules/matrix-client/utils/getEventId.ts`

---

## 3. REPLY PAYLOAD SYSTEM

**Type Definitions** (`src/@types/timeline.d.ts`):
```typescript
type TimelineReplyPayload = {
  eventId: string;      // ID of message being replied to
  senderName: string;   // Name of original sender
  content: string;      // Text content of original message
};

type TimelineLongPressPayload = {
  event: EventTimelineItem;
  content: string;
};
```

**Jotai Atoms** (`src/modules/timeline/jotai/atoms.ts`):
```typescript
const longPressPayload = atom<TimelineLongPressPayload | null>(null);
const replyPayload = atom<TimelineReplyPayload | null>(null);

export const TimelineAtoms = {
  longPressPayload,
  replyPayload,
};
```

**Reply Extraction** (TextMessage.tsx, lines 36-56):
```typescript
const replyPayload = (): TimelineReplyPayload | null => {
  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return null;

  const inReplyTo = event.content.inner.content.inReplyTo;
  if (!inReplyTo) return null;

  const eventDetails = inReplyTo.event();
  if (eventDetails.tag !== EmbeddedEventDetails_Tags.Ready) return null;

  const senderName =
    eventDetails.inner.senderProfile.tag === ProfileDetails_Tags.Ready
      ? (eventDetails.inner.senderProfile.inner.displayName ??
        eventDetails.inner.sender)
      : eventDetails.inner.sender;

  return {
    eventId: inReplyTo.eventId(),
    senderName,
    content: getMessageTextContent(eventDetails.inner.content),
  };
};
```

**ReplyPayload Component** (`src/screens/room/fragments/reply-paylaod/ReplyPayload.tsx`):
- Displays: sender name, reply content text
- Shows in message bubbles and input area
- Has clear button to remove reply

